from pathlib import Path

path = Path('src/main/java/com/metallum/client/metal/render/MetalRenderPass.java')
text = path.read_text()

anchor = '''            MemorySegment indexHandle = ((MetalGpuBuffer) indexBuffer).nativeHandle();\n            if (TerrainSceneSnapshot.GPU_ICB_ENABLED\n                    && owner.hasReusableGpuIcb(device, primitiveType, snapshot)) {'''
replacement = '''            MemorySegment indexHandle = ((MetalGpuBuffer) indexBuffer).nativeHandle();\n\n            // The visible lane is frame/epoch state and must be attempted before\n            // an immutable all-visible ICB can be reused. The candidate snapshot\n            // is authoritative only when every source draw resolves to exactly\n            // one live candidate, and ownerForEpoch returns only the producer\n            // encoded earlier in this same terrain draw scope. Any rejection\n            // falls through to the existing all-visible GPU/CPU paths.\n            if (TerrainCandidateSnapshot.VISIBLE_GPU_ICB_ENABLED) {\n                TerrainCandidateSnapshot candidates = TerrainCandidateRegistry.latestSnapshot();\n                TerrainVisibleDrawPlan visiblePlan = candidates == null\n                        ? null\n                        : TerrainVisibleDrawPlan.tryBuild(snapshot, candidates);\n                if (visiblePlan != null) {\n                    MemorySegment visibilityOwner = TerrainGpuVisibilityProbe.ownerForEpoch(\n                            visiblePlan.candidateEpoch(), visiblePlan.candidateCount()\n                    );\n                    if (!MetalNativeBridge.isNullHandle(visibilityOwner)) {\n                        MemorySegment retainedEncoder = commandEncoder.endEncoderForTerrainGpuAuthoring();\n                        try {\n                            if (!MetalNativeBridge.isNullHandle(retainedEncoder)\n                                    && owner.encodeVisibleGpu(\n                                    device,\n                                    retainedEncoder,\n                                    primitiveType,\n                                    indexType,\n                                    indexHandle,\n                                    pipelineHandle,\n                                    snapshot,\n                                    visiblePlan,\n                                    visibilityOwner,\n                                    drawCount\n                            )) {\n                                MTLRenderCommandEncoder reopened = renderEncoder();\n                                bindDrawState(reopened);\n                                if (owner.execute(\n                                        device,\n                                        reopened,\n                                        primitiveType,\n                                        indexType,\n                                        indexHandle,\n                                        pipelineHandle,\n                                        snapshot,\n                                        drawCount\n                                )) {\n                                    return true;\n                                }\n                            }\n                        } finally {\n                            if (!MetalNativeBridge.isNullHandle(retainedEncoder)) {\n                                MetalNativeBridge.metallum_release_object(retainedEncoder);\n                            }\n                        }\n                        // A visible attempt owns epoch-specific state. Never let\n                        // a failed execute leave that mask reusable as immutable\n                        // draw content while the conservative fallback continues.\n                        owner.invalidateVisibilityAuthored();\n                        enc = renderEncoder();\n                        bindDrawState(enc);\n                    }\n                }\n            }\n\n            if (TerrainSceneSnapshot.GPU_ICB_ENABLED\n                    && owner.hasReusableGpuIcb(device, primitiveType, snapshot)) {'''
assert anchor in text, 'MetalRenderPass authority anchor drifted'
text = text.replace(anchor, replacement, 1)
path.write_text(text)

contract = Path('src/test/java/com/metallum/client/metal/render/Metal4TerrainVisibleIcbAuthorityContractTest.java')
contract.write_text('''package com.metallum.client.metal.render;\n\nimport org.junit.jupiter.api.Test;\n\nimport java.io.IOException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\n\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nfinal class Metal4TerrainVisibleIcbAuthorityContractTest {\n    @Test\n    void realTerrainSubmissionConsumesVisiblePlanBeforeAllVisibleReuse() throws IOException {\n        String source = Files.readString(Path.of(\n                "src/main/java/com/metallum/client/metal/render/MetalRenderPass.java"\n        ));\n        int visible = source.indexOf("TerrainVisibleDrawPlan.tryBuild(snapshot, candidates)");\n        int owner = source.indexOf("TerrainGpuVisibilityProbe.ownerForEpoch(", visible);\n        int encode = source.indexOf("owner.encodeVisibleGpu(", owner);\n        int execute = source.indexOf("owner.execute(", encode);\n        int reusable = source.indexOf("owner.hasReusableGpuIcb(device, primitiveType, snapshot)");\n        assertTrue(visible >= 0, "real draw path must build the visible mapping");\n        assertTrue(owner > visible, "visible mapping must select its exact producer epoch");\n        assertTrue(encode > owner, "real draw path must invoke the visible ICB author");\n        assertTrue(execute > encode, "visible ICB must execute through the existing owner");\n        assertTrue(reusable > execute, "epoch-visible authority must precede all-visible immutable reuse");\n    }\n\n    @Test\n    void visibleFailureFallsThroughInsteadOfDroppingDrawAuthority() throws IOException {\n        String source = Files.readString(Path.of(\n                "src/main/java/com/metallum/client/metal/render/MetalRenderPass.java"\n        ));\n        int visible = source.indexOf("owner.encodeVisibleGpu(");\n        int invalidate = source.indexOf("owner.invalidateVisibilityAuthored();", visible);\n        int allVisible = source.indexOf("owner.encodeGpu(", invalidate);\n        int finalFallback = source.indexOf("return owner.execute(", allVisible);\n        assertTrue(visible >= 0);\n        assertTrue(invalidate > visible);\n        assertTrue(allVisible > invalidate, "visible failure must continue into all-visible GPU authoring");\n        assertTrue(finalFallback > allVisible, "existing CPU ICB/indirect fallback must remain reachable");\n    }\n}\n''')
